SELECT distinct d.RESOURCE_ID AS id, d.RESOURCE_NAME AS label, d.RESOURCE_TYPE_ID as pid, '1' as type, '' as icon, d.resource_property FROM vm_emergency_resource_info t1 left join resource_conf d on t1.resource_id = d.resource_id left join resource_type z on d.resource_type_id=z.resource_type_id and d.tenant_id = z.tenant_id and d.industry_code = z.industry_code where t1.delete_flag = 0 and d.DELETE_FLAG = 0 and z.delete_flag = 0 and t1.import_flag = 0 and d.status='0' and d.tenant_id = #{tenantId,jdbcType=VARCHAR} and d.industry_code = #{industryCode,jdbcType=VARCHAR}
AND t1.event_code = #{eventCode}
AND t1.stage_id = #{stageId}
AND t1.task_id = #{taskId}
AND t1.resource_id = #{resourceId}
${dataScope}
